algorithms.pseudocode:
function INTERLEAVING_DISTANCE(w_F, w_G, S):
    best <- 0
    for sigma in S:
        best <- max(best, |w_F(sigma) - w_G(sigma)|)
    return best

function IS_INTERLEAVED(w_F, w_G, delta, S):
    if delta < 0: return false
    return INTERLEAVING_DISTANCE(w_F, w_G, S) <= delta

function PULLBACK(f, w_F):
    return function(sigma):
        image <- { f(v) : v in sigma }   # deduplicated finite set
        return w_F(image)

# d(PULLBACK(f, F), PULLBACK(f, G)) <= d(F, G)            (always)
# d(PULLBACK(f, F), PULLBACK(f, G))  = d(F, G)            (f surjective)

function DIAM_WEIGHT(d):
    return function(sigma):
        best <- 0
        for x in sigma:
            for y in sigma:
                best <- max(best, d(x, y))
        return best
